        category = "Vendor",
        source = "Jepetto Joybuzz or his Clockwork Assistant - The Wonderworks, Northrend Dalaran",
        npcId = 29478,
        requirements = "Either faction; enough gold for the vendor price.",
        cost = "250 gold before reputation discounts.",
        tips = "The Wonderworks is the toy shop, not Breanni's pet shop. Reputation discounts explain some lower prices quoted in comments. Place it on clear ground. Old comments describe forcing an entire city to /train; later Retail changes restrict or suppress that interaction. The train itself still appears, and a Train Wrecker can destroy the placed set.",
        effect = "Places a miniature train track and moving train; 30-minute cooldown.",
        waypoints = {
            {
                mapID = 125,
                x = 0.446,
                y = 0.45799999999999996,
                step = 2,
                label = "The Wonderworks - Jepetto and Clockwork Assistant",
                mapName = "Dalaran (Northrend)",
            },
        },
        itemId = 44606,
        name = "Toy Train Set",
        stepCount = 4,
        acquisition = "Difficulty: Easy - Buy the inexpensive toy from its year-round Dalaran vendor.\n\n1. Travel to Dalaran above Crystalsong Forest in Northrend. The portal to Crystalsong Forest in your capital's portal room reaches this city; the Dalaran Hearthstone reaches the Legion city instead.\n\n2. Enter The Wonderworks on the western side of Runeweaver Square, around 44.6, 45.8. Speak to Jepetto Joybuzz or the Clockwork Assistant inside the toy shop.\n\n3. Find Toy Train Set in the vendor's pages and buy it for 250 gold before Kirin Tor discounts. It is a regular gold purchase; no tournament progress or seasonal event is required.\n\n4. Use Toy Train Set from your bags to add it to the account-wide Toy Box. Place it on clear ground. Old comments describe forcing an entire city to /train; later Retail changes restrict or suppress that interaction. The train itself still appears, and a Train Wrecker can destroy the placed set.",
        sourceType = "Vendor",
        wowheadUrl = "https://www.wowhead.com/item=44606",
        difficultyReason = "Buy the inexpensive toy from its year-round Dalaran vendor.",
